#include "native-bridge.h"
#include "runtime.h"
#include "leb128.h"

#include <cstring>
#include <functional>


static runtime *xlr8_current_rt = nullptr;
static byte_p   xlr8_sys_args_pc = nullptr;


void xlr8_set_runtime(runtime *rt)
// ----------------------------------------------------------------------------
//   Select the runtime used by native helper calls
// ----------------------------------------------------------------------------
{
    xlr8_current_rt = rt;
}


runtime *xlr8_get_runtime()
// ----------------------------------------------------------------------------
//   Return the runtime used by native helper calls
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt;
}


void xlr8_null_opcode()
// ----------------------------------------------------------------------------
//   Trap for a null opcode
// ----------------------------------------------------------------------------
{
    record(runtime_error, "Hit null opcode at runtime");
    exit(1);
}


void xlr8_user_opcode()
// ----------------------------------------------------------------------------
//   Trap for an undefined user opcode
// ----------------------------------------------------------------------------
{
    record(runtime_error, "Hit undefined user opcode at runtime");
    exit(1);
}


void xlr8_undef_opcode()
// ----------------------------------------------------------------------------
//   Trap for an undefined opcode
// ----------------------------------------------------------------------------
{
    record(runtime_error, "Hit 'undef' opcode at runtime");
    exit(1);
}


void xlr8_set_sys_args(byte_p args)
// ----------------------------------------------------------------------------
//   Remember bytecode pointer for the next sys call
// ----------------------------------------------------------------------------
{
    xlr8_sys_args_pc = args;
}


void xlr8_store_float_local(byte d, uint32_t bits)
// ----------------------------------------------------------------------------
//   Write a float into a bytecode local using interpreter frame layout
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    float v = 0;
    memcpy(&v, &bits, sizeof(v));
    memcpy((float *) &xlr8_current_rt->frame[d], &v, sizeof(v));
}


void xlr8_float_binop(unsigned op, byte d, byte s)
// ----------------------------------------------------------------------------
//   Apply a float binop in C (Linux JIT avoids inline FP before sys)
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    float a = 0;
    float b = 0;
    float r = 0;
    memcpy(&a, (float *) &rt.frame[d], sizeof(a));
    memcpy(&b, (float *) &rt.frame[s], sizeof(b));
    switch (op)
    {
    case 0: r = a + b; break;
    case 1: r = a - b; break;
    case 2: r = a * b; break;
    case 3: r = a / b; break;
    default: return;
    }
    uint32_t bits = 0;
    memcpy(&bits, &r, sizeof(bits));
    rt.frame[d] = value_t(uint64_t(bits));
}


void *xlr8_runtime_fn(cstring name)
// ----------------------------------------------------------------------------
//   Resolve a native helper name to a function pointer
// ----------------------------------------------------------------------------
{
    struct entry { cstring name; void *fn; };
    static entry table[] = {
        { "xlr8_enter",    (void *) xlr8_enter },
        { "xlr8_leave",    (void *) xlr8_leave },
        { "xlr8_sync_args", (void *) xlr8_sync_args },
        { "xlr8_get_arg",  (void *) xlr8_get_arg },
        { "xlr8_set_arg",  (void *) xlr8_set_arg },
        { "xlr8_resolve",  (void *) xlr8_resolve },
        { "xlr8_sys",      (void *) xlr8_sys },
        { "xlr8_jit_addr", (void *) xlr8_jit_addr },
        { "xlr8_after_sys", (void *) xlr8_after_sys },
        { "xlr8_dispatch", (void *) xlr8_dispatch },
        { "xlr8_store_float_local", (void *) xlr8_store_float_local },
        { "xlr8_float_binop",       (void *) xlr8_float_binop },
        { "xlr8_push_value",      (void *) xlr8_push_value },
        { "xlr8_pop_value",       (void *) xlr8_pop_value },
        { "xlr8_push_flags_val",  (void *) xlr8_push_flags_val },
        { "xlr8_pop_flags_val",   (void *) xlr8_pop_flags_val },
        { "xlr8_save_jit_link",   (void *) xlr8_save_jit_link },
        { "xlr8_load_jit_link",   (void *) xlr8_load_jit_link },
        { "xlr8_store_global",    (void *) xlr8_store_global },
        { "xlr8_load_global",     (void *) xlr8_load_global },
        { "xlr8_set_flags",       (void *) xlr8_set_flags },
        { "xlr8_get_flags",       (void *) xlr8_get_flags },
        { "xlr8_get_frame",       (void *) xlr8_get_frame },
        { "xlr8_store_local",     (void *) xlr8_store_local },
        { "xlr8_load_local",      (void *) xlr8_load_local },
    };
    for (entry &e : table)
        if (!strcmp(e.name, name))
            return e.fn;
    return nullptr;
}


stack_p xlr8_enter(byte locals)
// ----------------------------------------------------------------------------
//   Allocate a bytecode frame with the given number of locals
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return nullptr;
    runtime &rt = *xlr8_current_rt;
    stack_p caller = rt.frame;
    stack_p frame  = rt.enter(locals);
    rt.arg_locals = caller;
    return frame;
}


stack_p xlr8_leave()
// ----------------------------------------------------------------------------
//   Pop the current bytecode frame
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return nullptr;
    runtime &rt = *xlr8_current_rt;
    stack_p frame = rt.leave();
    rt.arg_locals = rt.arguments();
    return frame;
}


void xlr8_sync_args()
// ----------------------------------------------------------------------------
//   Point arg_locals at the caller frame for get/set before enter
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->arg_locals = xlr8_current_rt->frame;
}


void xlr8_get_arg(byte d, byte s)
// ----------------------------------------------------------------------------
//   Copy argument slot s into bytecode local d
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    rt.frame[d] = rt.arg_locals[s];
}


void xlr8_set_arg(byte d, byte s)
// ----------------------------------------------------------------------------
//   Copy bytecode local s into argument slot d
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    rt.arg_locals[d] = rt.frame[s];
}


byte_p xlr8_resolve(tok_t t)
// ----------------------------------------------------------------------------
//   Resolve an undefined token to its implementation address
// ----------------------------------------------------------------------------
{
    tok_t impl = 0;
    return xlr8_resolve_impl(t, &impl);
}


byte_p xlr8_resolve_impl(tok_t t, tok_t *impl_tok)
// ----------------------------------------------------------------------------
//   Resolve call/jmp target, following op_undef stubs to the implementation
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return nullptr;
    runtime &rt = *xlr8_current_rt;
    byte_p pc = nullptr;
    if (rt.resolve(t, t, pc, false))
    {
        if (impl_tok)
        {
            auto it = rt.defined.find(t);
            *impl_tok = (it != rt.defined.end()) ? (*it).second : t;
        }
        return pc;
    }
    byte_p tp = xlr8_bytecode_start(t);
    if (tp && *tp == op_undef)
    {
        byte_p ucp = tp + 1;
        tok_t name = leb128<tok_t>(ucp);
        if (rt.resolve(name, name, pc, false))
        {
            if (impl_tok)
            {
                auto it = rt.defined.find(name);
                *impl_tok = (it != rt.defined.end()) ? (*it).second : name;
            }
            return pc;
        }
    }
    if (t > 0 && t < rt.tokens.size())
    {
        pc = byte_p(rt.tok(t));
        if (pc && *pc != op_undef)
        {
            if (impl_tok)
                *impl_tok = t;
            return pc;
        }
    }
    return nullptr;
}


byte_p xlr8_bytecode_start(tok_t t)
// ----------------------------------------------------------------------------
//   Return the first bytecode byte of a token's payload
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || t >= xlr8_current_rt->tokens.size())
        return nullptr;
    return byte_p(xlr8_current_rt->tok(t));
}


byte_p xlr8_bytecode_end(tok_t t)
// ----------------------------------------------------------------------------
//   Return one-past-last byte of a token's bytecode payload
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || t >= xlr8_current_rt->tokens.size())
        return nullptr;
    byte_p tp = xlr8_current_rt->tokens[t];
    size_t len = leb128<size_t>(tp);
    return byte_p(xlr8_current_rt->tok(t)) + len;
}


void xlr8_push_value(uintptr_t v)
// ----------------------------------------------------------------------------
//   Push a value on the bytecode evaluation stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->push(v);
}


uintptr_t xlr8_pop_value()
// ----------------------------------------------------------------------------
//   Pop a value from the bytecode evaluation stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        return xlr8_current_rt->pop();
    return 0;
}


void xlr8_store_global(byte g, byte s)
// ----------------------------------------------------------------------------
//   Store bytecode local s into global slot g
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    if (size_t(g) < rt.globals.size())
        rt.globals[g] = value_t(rt.frame[s]);
}


void xlr8_load_global(byte d, byte g)
// ----------------------------------------------------------------------------
//   Load global slot g into bytecode local d
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return;
    runtime &rt = *xlr8_current_rt;
    if (size_t(g) < rt.globals.size())
        rt.frame[d] = value_t(rt.globals[g]);
}


void xlr8_set_flags(uint64_t flags)
// ----------------------------------------------------------------------------
//   Update runtime flags from the JIT flags register
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->flags = flags;
}


uint64_t xlr8_get_flags()
// ----------------------------------------------------------------------------
//   Return runtime flags for reloading the JIT flags register
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? xlr8_current_rt->flags : 0;
}


stack_p xlr8_get_frame()
// ----------------------------------------------------------------------------
//   Return runtime frame pointer for reloading the JIT frame register
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? xlr8_current_rt->frame : nullptr;
}


void xlr8_store_local(byte n, uintptr_t v)
// ----------------------------------------------------------------------------
//   Store a value into a bytecode local via the runtime frame
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->frame[n] = ularge_t(v);
}


uintptr_t xlr8_load_local(byte n)
// ----------------------------------------------------------------------------
//   Load a bytecode local from the runtime frame
// ----------------------------------------------------------------------------
{
    return xlr8_current_rt ? uintptr_t(xlr8_current_rt->frame[n]) : 0;
}


void xlr8_save_jit_link(uintptr_t link)
// ----------------------------------------------------------------------------
//   Save the native return link for JIT epilogue
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        xlr8_current_rt->jit_link = link;
}


uintptr_t xlr8_load_jit_link()
// ----------------------------------------------------------------------------
//   Restore the native return link for JIT epilogue
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
        return xlr8_current_rt->jit_link;
    return 0;
}


void xlr8_push_flags_val(uint64_t flags)
// ----------------------------------------------------------------------------
//   Push the runtime flags register on the bytecode stack
// ----------------------------------------------------------------------------
{
    if (xlr8_current_rt)
    {
        xlr8_current_rt->flags = flags;
        xlr8_current_rt->push(flags);
    }
}


uint64_t xlr8_pop_flags_val()
// ----------------------------------------------------------------------------
//   Pop flags from the bytecode stack into the runtime
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    uint64_t flags = xlr8_current_rt->pop<uint64_t>();
    xlr8_current_rt->flags = flags;
    return flags;
}


int xlr8_sys(tok_t t, byte_p args)
// ----------------------------------------------------------------------------
//   Invoke a native syscall with bytecode arguments at args
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    if (args)
        xlr8_current_rt->pc = args;
    else if (xlr8_sys_args_pc)
        xlr8_current_rt->pc = xlr8_sys_args_pc;

    return xlr8_current_rt->native(t) ? 1 : 0;
}


static uintptr_t xlr8_jit_addr_impl(uintptr_t addr)
// ----------------------------------------------------------------------------
//   Map a bytecode PC (or an already-native PC from pca) to a code address
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt || !xlr8_current_rt->jit_code)
        return 0;
    runtime &rt = *xlr8_current_rt;
    uintptr_t base = uintptr_t(rt.jit_code);
    size_t code_top = 0;
    for (auto const &entry : rt.jit_pc_off)
        if (entry.second > code_top)
            code_top = entry.second;
    if (addr >= base && addr < base + code_top + 4096u)
        return addr;

    auto it = rt.jit_pc_off.find(byte_p(addr));
    if (it == rt.jit_pc_off.end())
    {
        auto next = rt.jit_pc_off.lower_bound(byte_p(addr));
        if (next == rt.jit_pc_off.end())
            return 0;
        it = next;
    }
    return base + it->second;
}


uintptr_t xlr8_jit_addr(uintptr_t bc_pc)
// ----------------------------------------------------------------------------
//   Map a bytecode PC to a native code address
// ----------------------------------------------------------------------------
{
    return xlr8_jit_addr_impl(bc_pc);
}


uintptr_t xlr8_after_sys(uintptr_t expected_next_pc)
// ----------------------------------------------------------------------------
//   If a sys native changed pc, return the native address to continue at
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    uintptr_t pc = uintptr_t(xlr8_current_rt->pc);
    if (pc == expected_next_pc)
        return 0;
    return xlr8_jit_addr_impl(pc);
}


uintptr_t xlr8_dispatch(byte s, uintptr_t table_pc)
// ----------------------------------------------------------------------------
//   Run dispatch table logic at table_pc and return native address for new pc
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    runtime &rt = *xlr8_current_rt;
    rt.pc = byte_p(table_pc);
    value_t ref = *rt.local<value_t>(s);
    rt.pc = rt.dispatch(rt.pc, ref, std::greater_equal<intptr_t>());
    return xlr8_jit_addr_impl(uintptr_t(rt.pc));
}


int xlr8_user_op(byte op, uintptr_t args_pc)
// ----------------------------------------------------------------------------
//   Invoke a user-defined opcode handler at args_pc
// ----------------------------------------------------------------------------
{
    if (!xlr8_current_rt)
        return 0;
    runtime &rt = *xlr8_current_rt;
    rt.pc = byte_p(args_pc);
    return rt.user_operation(op) ? 1 : 0;
}


#define REG(n)          pc++;
#define DST             REG(d)
#define SRC             REG(s)
#define XTRA            REG(x)
#define LEN             REG(l)
#define IVAL            REG(i)
#define UVAL            REG(u)
#define PRED            REG(p)
#define KSHIFT          REG(k)
#define ARG(type, name) leb128<type>(pc);
#define TOK             ARG(tok_t, t)
#define BRA             ARG(broff_t,b)
#define KINT            ARG(value_t,  kint)
#define KNAT            ARG(uvalue_t, knat)
#define KLEN            ARG(size_t, klen)
#define ISTREAM         KNAT;
#define OSTREAM         KNAT;

void xlr8_skip_sys_args(tok_t t, byte_p &pc)
// ----------------------------------------------------------------------------
//   Advance pc past the arguments of a sys call during translation
// ----------------------------------------------------------------------------
{
#define NATIVE(name, decl, code)        if (t == runtime::sys_##name) { decl; }
#include "native.tbl"
}


size_t xlr8_sys_branch_targets(tok_t t, byte_p pc, uintptr_t *out, size_t max)
// ----------------------------------------------------------------------------
//   Return bytecode branch targets referenced in a sys call's arguments
// ----------------------------------------------------------------------------
{
    size_t branches = 0;
#undef  BRA
#define BRA                                     \
    byte_p bpc = pc;                            \
    broff_t b = leb128<broff_t>(pc);            \
    if (branches < max)                         \
        out[branches++] = uintptr_t(bpc + b);

#define NATIVE(name, decl, code)        if (t == runtime::sys_##name) { decl; }
#include "native.tbl"
    return branches;
}
